insert into public.faqs(question,answer,category,display_order,visible,is_demo) select 'What documents should I check before buying?','Check ownership papers, approvals, tax and utility clearance, and payment records. Have a lawyer review them.','Documentation',4,true,false where not exists(select 1 from public.faqs where question='What documents should I check before buying?');
